<span class="line"><span style="color:#E5C07B;">    IEnumerator</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">T</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#61AFEF;">GetEnumerator</span><span style="color:#ABB2BF;">();</span></span>
